const body = $input.first().json;
const queries = body.queries || body.query ? [body.query] : [];
if (!queries.length) throw new Error('queries array is required');
const apify_token = (body.apify_token || process.env.APIFY_API_TOKEN || '').trim();
if (!apify_token) throw new Error('apify_token required');
const admin_url = (body.admin_url || process.env.ADMIN_BASE_URL || 'http://127.0.0.1:8787').trim();
return queries.map(q => ({ json: { query: q, apify_token, admin_url, results_per_page: body.results_per_page || 10 } }));

const DENYLIST = ['reddit.com','g2.com','capterra.com','trustradius.com','getapp.com','producthunt.com','wikipedia.org','linkedin.com','softwareadvice.com','trustpilot.com','yelp.com','glassdoor.com','crunchbase.com','gartner.com','forrester.com','techcrunch.com','venturebeat.com'];
const results = $input.first().json;
const items = Array.isArray(results) ? results : [results];
const candidates = [];
for (const item of items) {
  const organicResults = item.organicResults || [];
  for (const r of organicResults) {
    const url = r.url || r.link || '';
    if (!url) continue;
    try {
      const host = new URL(url).hostname.replace(/^www\./,'');
      if (DENYLIST.some(d => host === d || host.endsWith('.'+d))) continue;
      candidates.push({ url, title: r.title || '', snippet: r.description || r.snippet || '', source: 'google_discovery' });
    } catch { /* skip malformed URLs */ }
  }
}
return candidates.map(c => ({ json: c }));
